2	 * The default movement strategy for animals.
3	 *
4	 * Priority order:
5	 *   1. Seek water when critically thirsty (waterLevel below threshold).
6	 *   2. Seek food when hungry (foodLevel below threshold).
7	 *   3. Move toward a mate.
8	 *   4. Wander to any free adjacent cell.
9	 *
10	 * Returns null only when every adjacent cell is occupied, causing the caller
11	 * to mark the animal as dead due to overcrowding.
12	 *
13	 * @version 2022.03.01
14	 */
15	public class StandardMovementStrategy implements MovementStrategy
16	{
17	    // Water level below which water becomes the top priority.
18	    private static final int WATER_URGENCY_THRESHOLD = 3;
19	    // Food level below which food becomes higher priority than finding a mate.
20	    private static final int FOOD_URGENCY_THRESHOLD  = 8;
21	
22	    @Override
23	    public Location selectDestination(Animal animal)
24	    {
25	        if(animal.getWaterLevel() < WATER_URGENCY_THRESHOLD) {
26	            Location loc = animal.findWater();
27	            if(loc != null) return loc;
28	        }
29	        if(animal.getFoodLevel() < FOOD_URGENCY_THRESHOLD) {
30	            Location loc = animal.findFood(animal.getPrey());
31	            if(loc != null) return loc;
32	        }
33	        Location loc = animal.findMate();
34	        if(loc != null) return loc;
35	        return animal.getField().freeAdjacentLocation(animal.getLocation());
36	    }
37	}
