6	/**
7	 * A simple predator-prey simulator, based on a rectangular field
8	 * containing rabbits and foxes.
9	 *
10	 * @version 2022.03.01
11	 */
12	public class Simulator
13	{
14	    // The default width for the grid.
15	    private static final int DEFAULT_WIDTH = 150;
16	    // The default depth of the grid.
17	    private static final int DEFAULT_DEPTH = 120;
18	
19	    // List of all actors in the simulation.
20	    private List<Actor> actors;
21	    // The current state of the field.
22	    private Field field;
23	    // The current step of the simulation.
24	    private int step;
25	    // A graphical view of the simulation.
26	    private SimulatorView view;
27	    // Whether it is currently day or night - determines each animal's behaviour.
28	    private boolean nightTime;
29	    // Handles initial population and dynamic entity creation.
30	    private PopulationManager populationManager;
31	
32	    /**
33	     * Construct a simulation field with default size.
34	     */
35	    public Simulator()
36	    {
37	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
38	    }
39	
40	    /**
41	     * Create a simulation field with the given size.
42	     * @param depth Depth of the field. Must be greater than zero.
43	     * @param width Width of the field. Must be greater than zero.
44	     */
45	    public Simulator(int depth, int width)
46	    {
47	        if(width <= 0 || depth <= 0) {
48	            System.out.println("The dimensions must be greater than zero.");
49	            System.out.println("Using default values.");
50	            depth = DEFAULT_DEPTH;
51	            width = DEFAULT_WIDTH;
52	        }
53	        nightTime = false;
54	        actors = new ArrayList<>();
55	        field = new Field(depth, width);
56	        populationManager = new PopulationManager(field, this);
57	
58	        view = new SimulatorView(depth, width, this);
59	        view.setColor(Gazelle.class, Color.ORANGE);
60	        view.setColor(Lion.class, Color.YELLOW);
61	        view.setColor(Hyena.class, Color.RED);
62	        view.setColor(Mouse.class, Color.GRAY);
63	        view.setColor(FennecFox.class, Color.MAGENTA);
64	        view.setColor(Grass.class, Color.GREEN);
65	        view.setColor(Lake.class, Color.BLUE);
66	
67	        reset();
68	    }
69	
70	    /**
71	     * Run the simulation from its current state for a reasonably long period.
72	     */
73	    public void runLongSimulation()
74	    {
75	        simulate(750);
76	    }
77	
78	    /**
79	     * Run the simulation from its current state for the given number of steps.
80	     * Stop before the given number of steps if it ceases to be viable.
81	     * @param numSteps The number of steps to run for.
82	     */
83	    public void simulate(int numSteps)
84	    {
