        }
    }
    @Override protected int getBreedingAge() { return SimulationConfiguration.LION_BREEDING_AGE; }
    @Override protected double getBreedingProbability() { return SimulationConfiguration.LION_BREEDING_PROBABILITY; }
    @Override protected int getMaxLitterSize() { return SimulationConfiguration.LION_MAX_LITTER_SIZE; }
    @Override public int getMaxAge() { return SimulationConfiguration.LION_MAX_AGE; }
    @Override protected Animal createOffspring(Field field, Location loc) { return new Lion(false, field, loc); }
    @Override protected double getHuntProbability() { return SimulationConfiguration.LION_HUNT_PROBABILITY; }
    public int getFoodValue() { return SimulationConfiguration.LION_FOOD_VALUE; }
    public double getHuntProb() { return SimulationConfiguration.LION_HUNT_PROBABILITY; }
