    {
        super.act(newGrass);
        decreaseWaterLevel();
        if(isAlive()) {
            giveBirth(newGrass);
            findWater();
        }
    }

    @Override
    protected int getMaxAge() { return SimulationConfiguration.GRASS_MAX_AGE; }

    @Override
    protected double getReproductionProbability() { return SimulationConfiguration.GRASS_REPRODUCTION_PROBABILITY; }

